package edu.pe.cibertec.saibm.usuario.infrastructure.persistence; import java.util.*; import java.util.UUID; import org.springframework.data.jpa.repository.*; import org.springframework.data.repository.query.Param; public interface UserJpaRepository extends JpaRepository<UserJpaEntity,UUID>{@Query("select u from UserJpaEntity u where :query='' or lower(u.firstName) like lower(concat('%',:query,'%')) or lower(u.lastName) like lower(concat('%',:query,'%')) or lower(u.email) like lower(concat('%',:query,'%'))")List<UserJpaEntity> search(@Param("query")String query);Optional<UserJpaEntity> findByEmailIgnoreCase(String email);}
